INSERT INTO `guide_chapters` (`id`, `title`, `summary`, `body`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES
	(1, 'BAB 1: Pemeriksaan Pra-Operasi Unit', 'Checklist wajib sebelum engine start.', '1. Lakukan walk-around inspection 360 derajat.\n2. Pastikan tidak ada kebocoran oli, solar, coolant, atau hydraulic oil.\n3. Cek level oli mesin, coolant radiator, dan bahan bakar sesuai standar pabrikan.\n4. Periksa kondisi ban/track, baut roda, dan selang hidrolik.\n5. Pastikan alat pemadam, seatbelt, lampu, dan klakson berfungsi.\n6. Dokumentasikan temuan awal melalui menu Temuan jika ada anomali.', 1, 1, '2026-05-24 00:50:45', '2026-05-24 00:50:45'),
	(2, 'BAB 2: Prosedur Engine Start dan Warming Up', 'Langkah aman menyalakan unit.', '1. Nyalakan engine pada idle, tanpa akselerasi mendadak.\n2. Biarkan warming up minimal 5 menit atau sesuai manual unit.\n3. Pantau panel indikator: oil pressure, temperature, battery charge.\n4. Operasikan silinder hidrolik perlahan tanpa beban untuk sirkulasi awal.\n5. Hentikan operasi jika indikator abnormal menyala merah.', 2, 1, '2026-05-24 00:50:45', '2026-05-24 00:50:45'),
	(3, 'BAB 3: Standar Pengisian HM Record', 'Flow input HM harian di aplikasi mobile.', '1. Pastikan aset sudah di-assign pada menu Aset Unit.\n2. Buka menu HM Record di beranda mobile.\n3. Verifikasi HM awal shift yang muncul otomatis.\n4. Input HM akhir shift berdasarkan odometer aktual unit.\n5. Simpan HM dan pastikan notifikasi sukses muncul.\n6. HM digunakan sistem untuk trigger preventive schedule dan monitoring utilitas.', 3, 1, '2026-05-24 00:50:45', '2026-05-24 00:50:45'),
	(4, 'BAB 4: Standar Pengisian Form P2H', 'Proses inspeksi P2H sebelum/selesai operasi.', '1. Buka Form P2H dan pastikan unit aktif sesuai assignment.\n2. Isi setiap item checklist dengan status Aman, Catatan, atau Rusak.\n3. Untuk item Rusak, pastikan deskripsi kondisi dicatat jelas.\n4. Submit form setelah seluruh item terisi.\n5. Cek tab Riwayat untuk memastikan data tersimpan.\n6. Gunakan data P2H untuk evaluasi harian compliance.', 4, 1, '2026-05-24 00:50:45', '2026-05-24 00:50:45'),
	(5, 'BAB 5: Registrasi Workshop dan Progress', 'Flow ketika unit membutuhkan penanganan workshop.', '1. Buat registrasi workshop melalui menu Workshop pada mobile.\n2. Tulis keluhan/gejala unit sejelas mungkin.\n3. Sistem membuat work order breakdown/corrective sesuai flow.\n4. Pantau progres pada halaman detail workshop (timeline proses).\n5. Koordinasikan dengan mechanic dan supervisor jika status on-hold/reject.\n6. Tutup loop dengan verifikasi status completed.', 5, 1, '2026-05-24 00:50:45', '2026-05-24 00:50:45'),
	(6, 'BAB 6: Preventive Maintenance dari Jadwal', 'Cara membaca due schedule preventive.', '1. Buka menu Preventive untuk melihat jadwal 30 hari ke depan.\n2. Prioritaskan item dengan status due dan overdue.\n3. Cocokkan due dengan HM/KM/date trigger unit.\n4. Buat work order dari jadwal bila diperlukan.\n5. Setelah eksekusi preventive, update status schedule di sistem.', 6, 1, '2026-05-24 00:50:45', '2026-05-24 00:50:45'),
	(7, 'BAB 7: Inventory dan Ketersediaan Spare Part', 'Validasi stok sebelum pekerjaan dimulai.', '1. Gunakan menu Inventory untuk cek spare part yang dibutuhkan.\n2. Verifikasi code part, nama part, lokasi, dan qty_available.\n3. Jika stok nol, koordinasikan replenishment sebelum pengerjaan kritikal.\n4. Catat penggunaan part di proses work order untuk traceability.', 7, 1, '2026-05-24 00:50:45', '2026-05-24 00:50:45'),
	(8, 'BAB 8: Pelaporan Temuan', 'Panduan input, update, dan tindak lanjut temuan.', '1. Buka menu Temuan lalu isi bagian aset dan deskripsi detail.\n2. Lampirkan foto bukti kondisi aktual.\n3. Submit temuan dan monitor status pada tab riwayat.\n4. Gunakan edit jika deskripsi perlu perbaikan sebelum ditindaklanjuti.\n5. Hapus data hanya jika laporan benar-benar salah input.\n6. Status resolved menandakan tindak lanjut sudah selesai.', 8, 1, '2026-05-24 00:50:45', '2026-05-24 00:50:45'),
	(9, 'BAB 9: K3 dan Batasan Operasional', 'Ketentuan keselamatan kerja saat operasi unit.', '1. Wajib APD lengkap: helm, sepatu safety, rompi, sarung tangan.\n2. Dilarang bypass alarm keselamatan unit.\n3. Dilarang menjalankan unit jika rem/steering/hydraulic tidak normal.\n4. Pastikan area kerja steril sebelum manuver atau pengangkatan beban.\n5. Hentikan operasi ketika visibility dan cuaca tidak aman.', 9, 1, '2026-05-24 00:50:45', '2026-05-24 00:50:45'),
	(10, 'BAB 10: Prosedur Darurat dan Eskalasi', 'Langkah saat kondisi kritis.', '1. Segera hentikan unit di area aman ketika terjadi abnormal kritis.\n2. Matikan engine sesuai prosedur shutdown darurat.\n3. Laporkan ke atasan langsung dan tim workshop melalui aplikasi.\n4. Dokumentasikan kronologi, indikator panel, serta foto kondisi.\n5. Jangan mengoperasikan ulang unit sebelum clearance dari pihak berwenang.', 10, 1, '2026-05-24 00:50:45', '2026-05-24 00:50:45');
